def folder_display(lop_key, folder_key):
    for lk, _, folders in CONTENT_TREE:
        if lk == lop_key:
            for fk, fname in folders:
                if fk == folder_key:
                    return fname
    return folder_key


def _load_pool_from_db(lop_key: str, folder_key: str) -> list:
    """Lấy câu hỏi từ questions_pool DB (do agent crawl về).
    Trả [] nếu bảng chưa tồn tại hoặc không có câu nào.
    """
    # folder_key → (subject, folder_type) mapping
    _FK_MAP = {
        "de_hk1_toan":       ("toan",      "hk1"),
        "de_hk2_toan_1":     ("toan",      "hk2"),
        # Lớp 2 (agent-crawled)
        "toan_2_hk1":        ("toan",      "hk1"),
        "toan_2_hk2":        ("toan",      "hk2"),
        "de_hsg_toan_2":     ("toan",      "hsg"),
        "toan_violympic_2":  ("toan",      "violympic"),
        "tieng_anh_2_hk1":   ("tieng_anh", "hk1"),
        "tieng_anh_2_hk2":   ("tieng_anh", "hk2"),
        "de_toan_6_hk2":  ("toan",      "hk2"),
        "de_toan_6_hk1":  ("toan",      "hk1"),
        "toan_7_hk1":     ("toan",      "hk1"),
        "toan_8_hk2":     ("toan",      "hk2"),
        "de_olympic_toan_6":  ("toan",  "violympic"),
        "toan_violympic_1":   ("toan",  "violympic"),
        "de_tieng_anh_6_hk2": ("tieng_anh", "hk2"),
        "tieng_anh_7_hk1":    ("tieng_anh", "hk1"),
    }
    mapping = _FK_MAP.get(folder_key)
    if not mapping:
        return []
    subject, folder_type = mapping
    try:
        from agent.db import get_pool_questions
        return get_pool_questions(lop_key, subject, folder_type)
    except Exception:
        return []


def gen_exam(lop_key, folder_key, n=15, seed=None, exam_no=1):
    """Sinh n câu cho lop_key + folder_key."""
    if seed is not None:
        random.seed(seed)

    # HSG Toán 6: mỗi đề_no = toàn bộ câu của 1 PDF (không random subset)
    if folder_key == "de_hsg_toan_6":
        pool = _HSG_TOAN_6_EXAMS.get(exam_no or 1, [])
        result = list(pool)
        random.shuffle(result)
        return result

    # HSG Toán 1: mỗi đề_no = 30 câu cố định từ hard pool, xáo trộn thứ tự
    if folder_key == "de_hsg_toan_1":
        pool = _HSG_TOAN_1_EXAMS.get(exam_no or 1, _HSG_TOAN_1_EXAMS[1])
        result = list(pool)
        random.shuffle(result)
        return result

    # HSG Anh 6: giữ nguyên thứ tự (Listening → Phonetics → Grammar → Reading)
    if folder_key == "de_hsg_anh_6":
        pool = _HSG_ANH_6_EXAMS.get(exam_no or 1, [])
        if not pool:
            return _placeholder(1, "", "Tiếng Anh", f"Đề HSG Anh 6 — Đề {exam_no or 1}")
        return list(pool)

    # Lớp 1 — HK2: mix generators + static pool + nâng cao
    if lop_key == "lop_1" and folder_key == "de_hk2_toan_1":
        gen_n = max(1, n // 4)          # ~5 câu sinh tự động
        nc_n  = min(5, len(_HK2_TOAN_1_NC))  # ~5 câu nâng cao
        static_n = n - gen_n - nc_n
        part1 = _gen_bao_meo_pool(gen_n, seed=seed)
        part2 = list(BAO_MEO_POOL)
        random.shuffle(part2)
        part3 = list(_HK2_TOAN_1_NC)
        random.shuffle(part3)
        result = part1 + part2[:static_n] + part3[:nc_n]
        random.shuffle(result)
        return result

    pool = _FOLDER_POOLS.get((lop_key, folder_key), [])

    # Merge với câu hỏi từ agent pool (DB) — dedup theo q text
    db_pool = _load_pool_from_db(lop_key, folder_key)
    if db_pool:
        existing_qs = {q["q"] for q in pool}
        new_qs = [q for q in db_pool if q["q"] not in existing_qs]
        pool = list(pool) + new_qs

    if not pool:
        name = folder_display(lop_key, folder_key)
        return _placeholder(1, "", name, name)

    if folder_key in _TIENG_ANH_FOLDERS:
        return gen_english_structured(pool, n, seed)

    result = list(pool)
    random.shuffle(result)
    return result[:n]
